package edu.pbs.hub.controller; import edu.pbs.hub.model.*;import edu.pbs.hub.repo.*;import edu.pbs.hub.config.AdminGuard;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import jakarta.servlet.http.HttpServletRequest;import org.springframework.beans.factory.annotation.Value;import java.util.*;import java.nio.file.*;
@RestController @RequestMapping("/api/papers") public class PaperController {private final PaperRepository papers;private final CourseRepository courses;private final AdminGuard guard;@Value("${app.upload-dir}") private String uploadDir; public PaperController(PaperRepository p,CourseRepository c,AdminGuard g){papers=p;courses=c;guard=g;}
@GetMapping public List<Paper> list(@RequestParam(required=false) Long courseId,@RequestParam(required=false) Integer semester,@RequestParam(required=false) String category,@RequestParam(required=false) Integer year,@RequestParam(required=false) String q){if(q!=null&&!q.isBlank())return papers.findBySubjectContainingIgnoreCaseOrDescriptionContainingIgnoreCase(q,q);if(courseId!=null&&semester!=null&&category!=null&&year!=null)return papers.findByCourseIdAndSemesterAndCategoryAndYearOrderBySubjectAsc(courseId,semester,category,year);if(courseId!=null&&semester!=null)return papers.findByCourseIdAndSemesterOrderByYearDesc(courseId,semester);if(courseId!=null)return papers.findByCourseIdOrderByYearDesc(courseId);return papers.findAll();}
@PostMapping public Paper create(@RequestBody Paper p,HttpServletRequest req){guard.check(req);return papers.save(p);}
@PostMapping("/upload") public Paper upload(@RequestParam Long courseId,@RequestParam Integer semester,@RequestParam String category,@RequestParam Integer year,@RequestParam String subject,@RequestParam(required=false) String subjectCode,@RequestParam(required=false) String regulation,@RequestParam(required=false) String description,@RequestParam MultipartFile file,HttpServletRequest req)throws Exception{guard.check(req);if(file.isEmpty()||!Objects.requireNonNull(file.getContentType()).equalsIgnoreCase("application/pdf"))throw new IllegalArgumentException("Please upload a PDF file.");Course c=courses.findById(courseId).orElseThrow();Path dir=Paths.get(uploadDir).toAbsolutePath();Files.createDirectories(dir);String clean=file.getOriginalFilename().replaceAll("[^A-Za-z0-9._-]","_");String filename=UUID.randomUUID()+"_"+clean;Files.copy(file.getInputStream(),dir.resolve(filename),StandardCopyOption.REPLACE_EXISTING);Paper p=new Paper();p.setCourse(c);p.setSemester(semester);p.setCategory(category);p.setYear(year);p.setSubject(subject);p.setSubjectCode(subjectCode);p.setRegulation(regulation);p.setDescription(description);p.setFileName(clean);p.setFileUrl("/files/"+filename);return papers.save(p);}
@PutMapping("/{id}") public Paper edit(@PathVariable Long id,@RequestBody Paper p,HttpServletRequest req){guard.check(req);Paper old=papers.findById(id).orElseThrow();old.setCourse(p.getCourse());old.setSemester(p.getSemester());old.setCategory(p.getCategory());old.setYear(p.getYear());old.setSubject(p.getSubject());old.setSubjectCode(p.getSubjectCode());old.setRegulation(p.getRegulation());old.setDescription(p.getDescription());return papers.save(old);}
@PostMapping("/{id}/download") public Paper download(@PathVariable Long id){Paper p=papers.findById(id).orElseThrow();p.incrementDownloads();return papers.save(p);}
@DeleteMapping("/{id}") public void delete(@PathVariable Long id,HttpServletRequest req){guard.check(req);papers.deleteById(id);} }
